Lemma find_segment_rsegs' : forall (x : Z),
  find_segment rsegs x 1 =
    if ((0x10000 <=? x) && (x + 1 <=? 0x2a000))%Z then Some Plain.Plain_segment_000
    else if ((0x2a000 <=? x) && (x + 1 <=? 0x7a000))%Z then Some Plain.Plain_segment_001
    else if ((0x7a000 <=? x) && (x + 1 <=? 0x80000))%Z then Some Plain.Plain_segment_002
    else if ((0x80000 <=? x) && (x + 1 <=? 0xb4000))%Z then Some Plain.Plain_segment_003
    else None.
Proof. intros x. reflexivity. Qed.

Lemma find_segment_high : forall x, 0xb4000 <= x -> find_segment rsegs x 1 = None.
Proof.
  intros x Hx. rewrite find_segment_rsegs'.
  destruct (Z.leb_spec 0x10000 x); destruct (Z.leb_spec (x + 1) 0x2a000); cbn [andb]; try lia;
  destruct (Z.leb_spec 0x2a000 x); destruct (Z.leb_spec (x + 1) 0x7a000); cbn [andb]; try lia;
  destruct (Z.leb_spec 0x7a000 x); destruct (Z.leb_spec (x + 1) 0x80000); cbn [andb]; try lia;
  destruct (Z.leb_spec 0x80000 x); destruct (Z.leb_spec (x + 1) 0xb4000); cbn [andb]; try lia; reflexivity.
Qed.

Lemma stk_high_of_wr : forall m A n, wr_at rsegs m A n -> 0xb4000 <= A -> stk rsegs m A (A + n).
Proof.
  intros m A n (H0 & H1 & W) HA. split; [lia|]. split; [lia|]. intros a Ha.
  specialize (W (a - A) ltac:(lia)). replace (A + (a - A)) with a in W by lia. split; [exact W|].
  unfold wview in W. unfold mrd. destruct (m (wa a)) as [b|] eqn:E; [exists b; reflexivity|]. exfalso.
  rewrite wa_unsigned in W by lia. rewrite find_segment_high in W by lia. apply W. reflexivity.
Qed.

Lemma rw_junk_of_wmono : forall m m' A cs,
  rw_cells rsegs m A cs -> wmono rsegs m m' -> 0xb4000 <= A -> exists junk, rw_cells rsegs m' A [CB (cells_size cs) junk].
Proof.
  intros m m' A cs RC WM HA.
  destruct RC as [[WF BA] WR]. pose proof (wr_at_transport rsegs m m' _ _ WR WM) as WR'.
  pose proof (stk_high_of_wr m' A _ WR' HA) as ST.
  destruct (stk_carve rsegs m' A (A + Z.of_nat (cells_size cs)) (cells_size cs) ST ltac:(lia)) as [_ [junk RC']].
  replace (A + Z.of_nat (cells_size cs) - Z.of_nat (cells_size cs)) with A in RC' by lia. exists junk. exact RC'.
Qed.

