Definition ipf_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word := [s11; s10; s9; s8; s7; s6; s5; s4; s3; s2; s1; s0; ra].

Definition ipf_pure (sp : word) (P IN E lo : Z) (c : pcore) (p0 : Z) (bs : list byte) : Prop :=
  pcore_ok c /\ lo + 4800 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0xb4000 <= p0) /\ p0 + Z.of_nat (length bs) <= lo /\ Z.of_nat (length bs) <= 8194
  /\ bv_unsigned sp <= P /\ P + 256 <= 2^64 /\ bv_unsigned sp <= IN /\ IN + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (P + 256 <= IN \/ IN + 8 <= P) /\ (P + 256 <= E \/ E + 24 <= P) /\ (IN + 8 <= E \/ E + 24 <= IN).

