Definition ipf_frame (m1 : mem) (sp : word) (j16 jt : list byte) (p bsz : Z) (bb : list byte) (vl nm : list cell) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -4288) [CB 16 j16]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -4272) [CB 24 jt]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -4248) [C8 (wz p)]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -4240) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096
  /\ rw_cells rsegs m1 (bv_unsigned sp + -136) vl /\ cells_size vl = 16%nat
  /\ rw_cells rsegs m1 (bv_unsigned sp + -120) nm /\ cells_size nm = 16%nat.

