(* [comment removed for export] *)
Definition ipf_exit_stmt (pc : Z) (a0_is_p : bool) (qd : Z) (Eres : ecv) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x s7x s8x s9x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (q : Z) (g : bool) (j16 jt : list byte) (p bsz : Z) (bb : list byte) (vl nm : list cell),
  ipf_ctx m m1 sp (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c1 pad7 pad2 p0 bs q EC_clear g ->
  ipf_frame m1 sp j16 jt p bsz bb vl nm ->
  ipf_pure sp P IN E lo c p0 bs -> dof_core c c1 -> p0 <= q <= p0 + Z.of_nat (length bs) ->
  p0 <= p -> p + qd <= p0 + Z.of_nat (length bs) -> q <= p + qd -> (a0_is_p = true -> a0 = wz p) ->
  evt rsegs (ipf_ret_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo c pad7 pad2 p0 bs q m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN) a0 a1 a2 a3 a4 a5 a6 a7
              s2x (wz P) s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

